svg.script:
(function(){
'use strict';
/* =========================================================
   1. UTILITIES
   ========================================================= */
var NS='http://www.w3.org/2000/svg';
var root=document.documentElement;
function E(tag,a,p){var e=document.createElementNS(NS,tag);if(a)for(var k in a)e.setAttribute(k,a[k]);if(p)p.appendChild(e);return e;}
function U(p,id,a){var e=E('use',a,p);e.setAttribute('href','#'+id);e._h=id;return e;}
function Tx(p,x,y,s,a){var o={x:x,y:y};if(a)for(var k in a)o[k]=a[k];var e=E('text',o,p);e.textContent=s;return e;}
function $(id){return document.getElementById(id);}
function rnd(a,b){return a+Math.random()*(b-a);}
function irnd(a,b){return Math.floor(a+Math.random()*(b-a+1));}
function clamp(v,a,b){return v<a?a:v>b?b:v;}
function lerp(a,b,t){return a+(b-a)*t;}
function f1(v){return Math.round(v*10)/10;}
function f2(v){return Math.round(v*100)/100;}
function eob(t){var c=1.70158;t-=1;return 1+(c+1)*t*t*t+c*t*t;}
function eo(t){return 1-(1-t)*(1-t);}
function eio(t){return t<0.5?2*t*t:1-Math.pow(-2*t+2,2)/2;}
function show(e,on){var v=on?'':'none';if(e._d!==v){e.style.display=v;e._d=v;}}
function setT(e,s){if(e._t!==s){e.setAttribute('transform',s);e._t=s;}}
function setA(e,k,v){var kk='_a'+k;if(e[kk]!==v){e.setAttribute(k,v);e[kk]=v;}}
function setH(e,id){if(e._h!==id){e.setAttribute('href','#'+id);e._h=id;}}
function setTxt(e,s){s=String(s);if(e._s!==s){e.textContent=s;e._s=s;}}
function setF(e,f){if(e._f!==f){if(f)e.setAttribute('filter',f);else e.removeAttribute('filter');e._f=f;}}
function fmtTime(s){s=Math.floor(s);var m=Math.floor(s/60),r=s%60;return m+':'+(r<10?'0':'')+r;}

/* =========================================================
   2. CONSTANTS & DATA
   ========================================================= */
var W=1280,H=720,GX=196,GY=116,TW=96,TH=108,ROWS=5,COLS=9;
function rowY(r){return GY+r*TH+86;}
function colX(c){return GX+c*TW+TW/2;}
var HOUSE_X=112,MOW_TRIGGER=GX-16,MOWER_X=170,SPAWN_X=1305,ZS=0.92;
var SUN_HUD={x:54,y:40};
var CARD_X=106,CARD_Y=12,CARD_W=66,CARD_H=84,CARD_STEP=72;
var SHOVEL={x:548,y:9,w:78,h:86};
var BEST_KEY='opus_showcase_garden-defense_best';

var PT=[
 {id:'sun',  name:'暖阳葵',   en:'SUNNY',  cost:50,  cd:7,  hp:300,  start:0,   desc:'定时产出阳光，经济之本'},
 {id:'pea',  name:'豌豆炮',   en:'PEA',    cost:100, cd:7,  hp:300,  start:0,   desc:'朝前方一颗颗发射豌豆'},
 {id:'dbl',  name:'连发豆',   en:'DOUBLE', cost:200, cd:8,  hp:300,  start:0,   desc:'一次连射两颗，火力翻倍'},
 {id:'ice',  name:'霜冻豆',   en:'FROST',  cost:175, cd:8,  hp:300,  start:0,   desc:'冰豆让僵尸变蓝、减速'},
 {id:'spud', name:'土豆盾',   en:'SPUD',   cost:50,  cd:20, hp:2600, start:0.35,desc:'超级耐啃，替大家挡住僵尸'},
 {id:'chili',name:'辣椒爆弹', en:'CHILI',  cost:150, cd:30, hp:1e9,  start:0.6, desc:'种下即爆，炸飞周围 3×3'}
];
var ZT=[
 {id:'basic', name:'普通僵尸',   hp:200, armor:0,    spd:19, pts:100, cost:1, trait:'慢吞吞，见啥啃啥'},
 {id:'cone',  name:'路锥僵尸',   hp:200, armor:370,  spd:19, pts:150, cost:2, trait:'头顶路锥，更耐打'},
 {id:'bucket',name:'水桶僵尸',   hp:200, armor:1100, spd:19, pts:250, cost:4, trait:'铁皮水桶，超级硬'},
 {id:'runner',name:'跑跑僵尸',   hp:320, armor:0,    spd:20, pts:200, cost:2, trait:'受伤后撒腿狂奔'},
 {id:'pole',  name:'晾衣杆僵尸', hp:320, armor:0,    spd:36, pts:200, cost:3, trait:'撑杆跳过第一株植物'}
];
var ZSKIN=[
 {leg:'zLegA',torso:'zTorsoA',arm:'zArmA',armB:'zArmAB',armS:'zArmAS',head:'zHeadA',acc:'none'},
 {leg:'zLegA',torso:'zTorsoA',arm:'zArmA',armB:'zArmAB',armS:'zArmAS',head:'zHeadA',acc:'zCone'},
 {leg:'zLegA',torso:'zTorsoA',arm:'zArmA',armB:'zArmAB',armS:'zArmAS',head:'zHeadA',acc:'zPail'},
 {leg:'zLegR',torso:'zTorsoR',arm:'zArmR',armB:'zArmRB',armS:'zArmRS',head:'zHeadB',acc:'zBand'},
 {leg:'zLegV',torso:'zTorsoV',arm:'zArmV',armB:'zArmVB',armS:'zArmVS',head:'zHeadB',acc:'none'}
];
var DIFFS=[
 {name:'简单',en:'EASY',  sub:'阳光充足', sun:200,sky:6.5, hp:0.8, spd:0.9, waves:8, flags:[4,8],   first:24,gap:26,b0:1,bs:0.9, mult:1,  unlock:[1,3,6,4,5], color:'#6cc644'},
 {name:'普通',en:'NORMAL',sub:'标准挑战', sun:125,sky:8.5, hp:1,   spd:1,   waves:10,flags:[5,10],  first:20,gap:23,b0:1,bs:1.2, mult:1.5,unlock:[1,2,6,3,4], color:'#f0a020'},
 {name:'困难',en:'HARD',  sub:'僵尸凶猛', sun:75, sky:10.5,hp:1.3, spd:1.12,waves:12,flags:[4,8,12],first:16,gap:20,b0:2,bs:1.45,mult:2,  unlock:[1,2,4,2,3], color:'#e8453a'}
];

/* =========================================================
   3. AUDIO (WebAudio synth, all wrapped in try/catch)
   ========================================================= */
var AU={ctx:null,master:null,sfx:null,mus:null,noise:null,muted:false,last:{}};
function auInit(){
  try{
    if(!AU.ctx){
      var C=window.AudioContext||window.webkitAudioContext; if(!C) return;
      var c=new C(); AU.ctx=c;
      AU.master=c.createGain(); AU.master.gain.value=AU.muted?0:0.9; AU.master.connect(c.destination);
      AU.sfx=c.createGain(); AU.sfx.gain.value=0.8; AU.sfx.connect(AU.master);
      AU.mus=c.createGain(); AU.mus.gain.value=0.5; AU.mus.connect(AU.master);
      var len=c.sampleRate, b=c.createBuffer(1,len,c.sampleRate), d=b.getChannelData(0);
      for(var i=0;i<len;i++) d[i]=Math.random()*2-1;
      AU.noise=b;
    }
    if(AU.ctx.state==='suspended') AU.ctx.resume();
  }catch(e){AU.ctx=null;}
}
function auOk(){return AU.ctx&&AU.ctx.state==='running';}
function can(n,gap){var t=performance.now();if(AU.last[n]&&t-AU.last[n]<gap*1000)return false;AU.last[n]=t;return true;}
function osc(type,f0,f1_,dur,vol,when,dest,att){
  if(!auOk())return;
  try{var c=AU.ctx,t=when||c.currentTime,o=c.createOscillator(),g=c.createGain();
    o.type=type;o.frequency.setValueAtTime(f0,t);if(f1_&&f1_!==f0)o.frequency.exponentialRampToValueAtTime(f1_,t+dur);
    g.gain.setValueAtTime(0.0001,t);g.gain.exponentialRampToValueAtTime(vol,t+(att||0.006));g.gain.exponentialRampToValueAtTime(0.0001,t+dur);
    o.connect(g);g.connect(dest||AU.sfx);o.start(t);o.stop(t+dur+0.03);}catch(e){}
}
function nz(dur,vol,type,fA,fB,q,when,dest){
  if(!auOk())return;
  try{var c=AU.ctx,t=when||c.currentTime,s=c.createBufferSource(),fl=c.createBiquadFilter(),g=c.createGain();
    s.buffer=AU.noise;fl.type=type;fl.frequency.setValueAtTime(fA,t);if(fB)fl.frequency.exponentialRampToValueAtTime(fB,t+dur);fl.Q.value=q||1;
    g.gain.setValueAtTime(vol,t);g.gain.exponentialRampToValueAtTime(0.0001,t+dur);
    s.connect(fl);fl.connect(g);g.connect(dest||AU.sfx);s.start(t,Math.random()*0.4);s.stop(t+dur+0.03);}catch(e){}
}
function now(){return AU.ctx?AU.ctx.currentTime:0;}
var SFX={
  plant:function(){osc('sine',560,170,0.18,0.32);nz(0.13,0.22,'lowpass',1000,200,1);},
  pop:function(){osc('sine',620,980,0.08,0.13);},
  shoot:function(){if(!can('shoot',0.05))return;osc('triangle',760,250,0.09,0.14);nz(0.05,0.07,'bandpass',2400,900,2);},
  splat:function(){if(!can('splat',0.045))return;nz(0.09,0.2,'lowpass',1700,300,1.2);osc('sine',280,120,0.07,0.1);},
  clank:function(){if(!can('clank',0.07))return;osc('square',1500,1150,0.07,0.05);osc('triangle',2300,2000,0.14,0.05);},
  chomp:function(){if(!can('chomp',0.1))return;var t=now();nz(0.07,0.28,'bandpass',520,300,3,t);nz(0.06,0.24,'bandpass',440,260,3,t+0.09);},
  boom:function(){nz(1,0.75,'lowpass',2600,60,0.8);osc('sine',130,32,0.8,0.65);osc('sawtooth',85,30,0.45,0.14);},
  sun:function(){if(!can('sun',0.04))return;var t=now();osc('sine',1318,0,0.18,0.16,t);osc('sine',1976,0,0.26,0.13,t+0.07);osc('triangle',2637,0,0.2,0.05,t+0.13);},
  mower:function(){if(!auOk())return;try{var c=AU.ctx,t=c.currentTime,o=c.createOscillator(),l=c.createOscillator(),lg=c.createGain(),g=c.createGain(),f=c.createBiquadFilter();
    o.type='sawtooth';o.frequency.setValueAtTime(70,t);o.frequency.linearRampToValueAtTime(120,t+0.3);f.type='lowpass';f.frequency.value=900;
    l.frequency.value=28;lg.gain.value=0.07;l.connect(lg);lg.connect(g.gain);
    g.gain.setValueAtTime(0.0001,t);g.gain.exponentialRampToValueAtTime(0.14,t+0.05);g.gain.setValueAtTime(0.14,t+1);g.gain.exponentialRampToValueAtTime(0.0001,t+1.5);
    o.connect(f);f.connect(g);g.connect(AU.sfx);o.start(t);l.start(t);o.stop(t+1.55);l.stop(t+1.55);}catch(e){}},
  groan:function(){if(!auOk()||!can('groan',3))return;try{var c=AU.ctx,t=c.currentTime,o=c.createOscillator(),v=c.createOscillator(),vg=c.createGain(),f=c.createBiquadFilter(),g=c.createGain(),b=rnd(95,140);
    o.type='sawtooth';o.frequency.setValueAtTime(b,t);o.frequency.linearRampToValueAtTime(b*1.25,t+0.35);o.frequency.linearRampToValueAtTime(b*0.8,t+0.9);
    v.frequency.value=6;vg.gain.value=5;v.connect(vg);vg.connect(o.frequency);
    f.type='bandpass';f.frequency.setValueAtTime(500,t);f.frequency.linearRampToValueAtTime(800,t+0.4);f.frequency.linearRampToValueAtTime(420,t+0.9);f.Q.value=4;
    g.gain.setValueAtTime(0.0001,t);g.gain.exponentialRampToValueAtTime(0.16,t+0.12);g.gain.exponentialRampToValueAtTime(0.0001,t+0.95);
    o.connect(f);f.connect(g);g.connect(AU.sfx);o.start(t);v.start(t);o.stop(t+1);v.stop(t+1);}catch(e){}},
  horn:function(){var t=now();[392,392,523].forEach(function(f,i){osc('square',f,0,i<2?0.14:0.5,0.07,t+i*0.16);osc('sawtooth',f/2,0,i<2?0.14:0.5,0.05,t+i*0.16);});},
  win:function(){var t=now();[523,659,784,1047,784,1047].forEach(function(f,i){osc('triangle',f,0,0.28,0.16,t+i*0.12);osc('sine',f*2,0,0.2,0.04,t+i*0.12);});[523,659,784].forEach(function(f){osc('triangle',f,0,1.2,0.08,t+0.75);});},
  lose:function(){var t=now();[392,370,349].forEach(function(f,i){osc('sawtooth',f,f*0.97,0.36,0.08,t+i*0.38);});
    if(!auOk())return;try{var c=AU.ctx,o=c.createOscillator(),v=c.createOscillator(),vg=c.createGain(),g=c.createGain(),s=t+1.14;o.type='sawtooth';o.frequency.setValueAtTime(330,s);o.frequency.linearRampToValueAtTime(262,s+1.1);
    v.frequency.value=7;vg.gain.value=8;v.connect(vg);vg.connect(o.frequency);g.gain.setValueAtTime(0.0001,s);g.gain.exponentialRampToValueAtTime(0.09,s+0.05);g.gain.exponentialRampToValueAtTime(0.0001,s+1.2);
    o.connect(g);g.connect(AU.sfx);o.start(s);v.start(s);o.stop(s+1.25);v.stop(s+1.25);}catch(e){}},
  click:function(){osc('triangle',900,650,0.06,0.12);},
  buzz:function(){if(!can('buzz',0.15))return;osc('square',170,150,0.15,0.07);osc('square',178,160,0.15,0.05);},
  shovel:function(){nz(0.18,0.25,'highpass',900,3000,1);osc('sine',320,520,0.12,0.1);},
  thud:function(){if(!can('thud',0.06))return;osc('triangle',260,120,0.14,0.16);nz(0.08,0.12,'lowpass',700,200,1);},
  whoosh:function(){nz(0.35,0.16,'bandpass',500,2200,1.5);},
  tick:function(){osc('sine',880,0,0.08,0.1);},
  go:function(){var t=now();[523,784,1047].forEach(function(f,i){osc('triangle',f,0,0.35,0.12,t+i*0.05);});},
  fuse:function(){nz(0.9,0.12,'bandpass',3000,6000,2);osc('sine',300,900,0.9,0.06);}
};
/* ---- music: cheerful looping 8-bar tune, look-ahead scheduled ---- */
var MUS={on:false,step:0,next:0,bpm:128};
var MEL=[];(function(){var m=[[0,76,2],[2,79,2],[4,81,1],[5,79,1],[6,76,2],[8,72,2],[10,74,1],[11,76,3],[14,79,2],
 [16,81,2],[18,79,2],[20,76,2],[22,72,2],[24,74,1],[25,76,2],[27,72,1],[28,69,4],
 [32,77,2],[34,81,2],[36,84,2],[38,81,2],[40,79,1],[41,77,1],[42,76,2],[44,74,2],[46,72,2],
 [48,74,2],[50,79,2],[52,83,2],[54,81,1],[55,79,1],[56,77,1],[57,76,1],[58,74,2],[60,67,4]];
 for(var i=0;i<64;i++)MEL[i]=null;m.forEach(function(n){MEL[n[0]]=n;});})();
var CHORDS=[[48,52,55],[45,48,52],[41,45,48],[43,47,50]];
function mf(m){return 440*Math.pow(2,(m-69)/12);}
function musicTick(){
  if(!MUS.on||!auOk())return;
  var c=AU.ctx,spb=60/MUS.bpm/2;
  if(MUS.next<c.currentTime-0.3)MUS.next=c.currentTime+0.06;
  while(MUS.next<c.currentTime+0.3){
    var s=MUS.step,t=MUS.next,ch=CHORDS[Math.floor(s/16)%4],b=s%8;
    if(b===0)osc('triangle',mf(ch[0]-12),0,0.34,0.13,t,AU.mus);
    else if(b===4)osc('triangle',mf(ch[2]-12),0,0.3,0.1,t,AU.mus);
    else if(b===6)osc('triangle',mf(ch[0]),0,0.14,0.07,t,AU.mus);
    if(s%4===2)for(var k=0;k<3;k++)osc('triangle',mf(ch[k]+12),0,0.17,0.03,t+k*0.012,AU.mus);
    var n=MEL[s];if(n){osc('sine',mf(n[1]),0,n[2]*spb*0.95+0.05,0.075,t,AU.mus);osc('triangle',mf(n[1]+12),0,0.12,0.018,t,AU.mus);}
    if(s%2===1)nz(0.035,0.025,'highpass',7000,0,1,t,AU.mus);
    MUS.step=(s+1)%64;MUS.next+=spb;
  }
}
function musicOn(v){MUS.on=v;if(v&&AU.ctx){MUS.next=AU.ctx.currentTime+0.08;}}
function setMute(m){AU.muted=m;try{if(AU.master)AU.master.gain.setTargetAtTime(m?0:0.9,AU.ctx.currentTime,0.02);}catch(e){}refreshMute();}
var refreshMute=function(){};

/* =========================================================
   4. SCENE BUILD (background, layers, HUD)
   ========================================================= */
var L={world:$('world'),bg:$('bg'),lawnFx:$('lawnFx'),rows:$('rows'),fx:$('fxL'),sun:$('sunL'),ghost:$('ghostL'),hud:$('hud'),ovl:$('ovl'),top:$('topUi')};
var clouds=[];
function pt(a,r,c){return c+f1(Math.cos(a)*r)+','+f1(Math.sin(a)*r)+' ';}
function buildDefsDyn(){
  var pet=$('sfPetals'),i,a,d='';
  for(i=0;i<14;i++)E('ellipse',{cx:0,cy:-25,rx:7.5,ry:12,transform:'rotate('+f1((i+0.5)*360/14)+')',fill:'#ff9f1c',stroke:'#c46a10','stroke-width':1.6},pet);
  for(i=0;i<14;i++)E('ellipse',{cx:0,cy:-23,rx:7,ry:11.5,transform:'rotate('+f1(i*360/14)+')',fill:'url(#gPetal)',stroke:'#d48612','stroke-width':1.6},pet);
  for(i=0;i<12;i++){a=i*Math.PI/6;d+=pt(a-0.17,18,'M')+pt(a,32,'L')+pt(a+0.17,18,'L')+'Z ';}
  E('path',{d:d,fill:'#ffd23a',stroke:'#f09a18','stroke-width':2,'stroke-linejoin':'round'},$('sunRays'));
  d='';for(i=0;i<8;i++){a=i*Math.PI/4;d+=pt(a-0.3,8,'M')+pt(a,14,'L')+pt(a+0.3,8,'L')+'Z ';}
  E('path',{d:d,fill:'#ffd23a',stroke:'#f09a18','stroke-width':1.2,'stroke-linejoin':'round'},$('icoSunRays'));
  var cp=E('clipPath',{id:'clipView'},root.querySelector('defs'));E('rect',{x:0,y:0,width:W,height:H},cp);
  L.world.setAttribute('clip-path','url(#clipView)');
}
function cloud(p,x,y,s){
  var g=E('g',null,p);
  E('path',{d:'M-46,10 C-60,10 -60,-8 -44,-8 C-42,-24 -18,-26 -12,-14 C-6,-30 24,-30 28,-12 C44,-16 52,2 40,10 Z',fill:'#bfe1f2',transform:'translate(2,5)'},g);
  E('path',{d:'M-46,10 C-60,10 -60,-8 -44,-8 C-42,-24 -18,-26 -12,-14 C-6,-30 24,-30 28,-12 C44,-16 52,2 40,10 Z',fill:'#ffffff'},g);
  clouds.push({g:g,x:x,y:y,s:s,v:4+s*5});
}
function windowAt(g,x,y,w,h){
  E('rect',{x:x-5,y:y-5,width:w+10,height:h+10,rx:5,fill:'#fffaf0',stroke:'#c9b48a','stroke-width':2},g);
  E('rect',{x:x,y:y,width:w,height:h,fill:'url(#gGlass)',stroke:'#8fb4c8','stroke-width':1.5},g);
  E('path',{d:'M'+(x+w/2)+','+y+' V'+(y+h)+' M'+x+','+(y+h/2)+' H'+(x+w),stroke:'#fffaf0','stroke-width':4},g);
  E('path',{d:'M'+(x+6)+','+(y+h*0.35)+' L'+(x+w*0.35)+','+(y+6),stroke:'#fff','stroke-width':3,opacity:.7,'stroke-linecap':'round'},g);
  E('path',{d:'M'+x+','+y+' h'+(w*0.28)+' q-6,'+(h*0.5)+' -'+(w*0.2)+','+h+' h-'+(w*0.08)+' Z',fill:'#ff9fb0',opacity:.85},g);
  E('path',{d:'M'+(x+w)+','+y+' h-'+(w*0.28)+' q6,'+(h*0.5)+' '+(w*0.2)+','+h+' h'+(w*0.08)+' Z',fill:'#ff9fb0',opacity:.85},g);
  E('rect',{x:x-9,y:y+h+4,width:w+18,height:12,rx:3,fill:'#b36b3a',stroke:'#6a3e18','stroke-width':1.5},g);
  for(var i=0;i<4;i++)U(g,'flower',{transform:'translate('+(x+6+i*(w-12)/3)+','+(y+h+6)+') scale(.55)',color:['#ff6f8a','#ffd23a','#ff9a3c','#c77dff'][i]});
}
function buildBg(){
  var g=L.bg,i,r,c,d,x,y;
  E('rect',{x:0,y:0,width:1090,height:132,fill:'url(#gSky)'},g);
  var cg=E('g',null,g);L.clouds=cg;
  cloud(cg,170,34,1);cloud(cg,470,58,0.75);cloud(cg,760,26,1.1);cloud(cg,1010,50,0.7);
  d='M0,118 ';for(i=0;i<=1100;i+=44){d+='Q'+(i+22)+','+(58+((i*37)%26))+' '+(i+44)+','+(92-((i*13)%12))+' ';}d+='L1100,132 L0,132 Z';
  E('path',{d:d,fill:'#5fae3e'},g);
  E('rect',{x:893,y:26,width:18,height:90,rx:4,fill:'#8a5a2c',stroke:'#5e3a18','stroke-width':2},g);
  [[868,34,30],[905,16,34],[940,36,28],[902,50,30]].forEach(function(q){E('circle',{cx:q[0],cy:q[1],r:q[2],fill:'#4f9a34',stroke:'#3a7a26','stroke-width':2},g);});
