function FxSys(layer,n){this.layer=layer;this.free=[];this.act=[];for(var i=0;i<n;i++){var u=U(layer,'none');show(u,false);this.free.push(u);}}
FxSys.prototype.add=function(id,x,y,o){
  var el=this.free.pop();if(!el){if(this.act.length>320)return null;el=U(this.layer,'none');}
  o=o||{};setH(el,id);show(el,true);
  if(o.color)el.setAttribute('color',o.color);
  var s0=o.s0==null?1:o.s0;
  var q={el:el,x:x,y:y,vx:o.vx||0,vy:o.vy||0,g:o.g||0,life:o.life||0.6,t:0,rot:o.rot||0,vr:o.vr||0,s0:s0,s1:o.s1==null?s0:o.s1,sy:o.sy||1,a0:o.a0==null?1:o.a0,fade:o.fade==null?0.5:o.fade,gr:o.gr||0,bn:o.bn||0,drag:o.drag||0};
  this.act.push(q);return q;
};
FxSys.prototype.update=function(dt){
  var a=this.act;
  for(var i=a.length-1;i>=0;i--){var q=a[i];q.t+=dt;
    if(q.t>=q.life){show(q.el,false);this.free.push(q.el);a[i]=a[a.length-1];a.pop();continue;}
    q.vy+=q.g*dt;if(q.drag){var k=Math.max(0,1-q.drag*dt);q.vx*=k;q.vy*=k;}
    q.x+=q.vx*dt;q.y+=q.vy*dt;q.rot+=q.vr*dt;
    if(q.gr&&q.y>q.gr){q.y=q.gr;if(q.bn&&q.vy>60){q.vy=-q.vy*q.bn;q.vx*=0.6;q.vr*=0.5;}else{q.vy=0;q.g=0;q.vx*=0.85;q.vr*=0.8;}}
  }
};
FxSys.prototype.render=function(){
  var a=this.act;
  for(var i=0;i<a.length;i++){var q=a[i],k=q.t/q.life,s=q.s0+(q.s1-q.s0)*k,al=k<q.fade?q.a0:q.a0*(1-(k-q.fade)/(1-q.fade));
    setT(q.el,'translate('+f1(q.x)+','+f1(q.y)+') rotate('+f1(q.rot)+') scale('+f2(s)+','+f2(s*q.sy)+')');
    setA(q.el,'opacity',f2(al));}
};
FxSys.prototype.clear=function(){var a=this.act;for(var i=0;i<a.length;i++){show(a[i].el,false);this.free.push(a[i].el);}a.length=0;};

