/* ---------- plants ---------- */
function makePlantDom(type){
  var o=pPool[type].pop();
  if(o)show(o.g,true);
  else{
    o={type:type};o.g=E('g');U(o.g,'pBase');o.a=E('g',null,o.g);
    if(type===0){U(o.a,'sfStem');o.h=E('g',null,o.a);o.glow=U(o.h,'sunGlowSm',{opacity:0});U(o.h,'sfPetals');o.face=U(o.h,'sfFace');}
    else if(type<=3){U(o.a,'peaCup');o.h=E('g',null,o.a);U(o.h,['peaBody','dblBody','iceBody'][type-1]);o.face=U(o.h,FACE0[type]);}
    else if(type===4){U(o.a,'spudBody');o.crack=U(o.a,'none');o.face=U(o.a,'spudFace0');}
    else{U(o.a,'chili');o.face=U(o.a,'chiliFace');}
  }
