function zombieAhead(p){for(var i=0;i<zombies.length;i++){var z=zombies[i];if(z.r===p.r&&!z.dead&&z.x>p.x-20&&z.x<1262)return true;}return false;}
function zombieNear(p){for(var i=0;i<zombies.length;i++){var z=zombies[i];if(z.r===p.r&&!z.dead&&z.x>p.x&&z.x<p.x+110)return true;}return false;}
function updPlant(p,dt){
  p.t+=dt;if(p.pop<1)p.pop=Math.min(1,p.pop+dt*2.6);
  if(p.flash>0)p.flash-=dt;if(p.hurt>0)p.hurt-=dt;if(p.recoil>0)p.recoil=Math.max(0,p.recoil-dt*6);
