  if(p.hurt>0)ox=Math.sin(G.t*55)*1.8;
  if(T===0){
    sy*=1+Math.sin(t*3.4)*0.018;
    setT(d.h,'translate(0,-48) rotate('+f1(Math.sin(t*1.7)*5)+') scale('+f2(1+p.glow*0.12)+')');
    setA(d.glow,'opacity',f2(p.glow*0.9));
