  for(k=0;k<8;k++)FX.add('fxSmoke',cx+rnd(-60,60),cy+rnd(-30,30),{vx:rnd(-30,30),vy:rnd(-60,-20),s0:1.2,s1:2.4,life:rnd(0.9,1.4),a0:0.7,fade:0.3});
  for(k=0;k<12;k++){var b=rnd(0,6.28);FX.add('fxSpark',cx,cy,{vx:Math.cos(b)*rnd(150,380),vy:Math.sin(b)*rnd(150,380),g:300,life:0.6,s0:1.4,s1:0.4,rot:rnd(0,360),vr:500});}
