/* ---------- peas ---------- */
function firePea(p,ice){
  var R=RL[p.r],el=R.peaFree.pop();
  if(!el)el=U(R.pe,'pea');
  setH(el,ice?'peaI':'pea');show(el,true);
  var x=p.x+40,y=p.y-36;
  peas.push({r:p.r,x:x,y:y,ice:ice,el:el,dmg:20});
  setT(el,'translate('+f1(x)+','+y+')');
  p.recoil=1;SFX.shoot();
  FX.add('fxPuff',x+2,y,{s0:0.35,s1:0.8,life:0.22,a0:0.8,fade:0.2});
}
function killPea(i){var q=peas[i];show(q.el,false);RL[q.r].peaFree.push(q.el);peas[i]=peas[peas.length-1];peas.pop();}
function updPeas(dt){
  for(var i=peas.length-1;i>=0;i--){
    var q=peas[i];q.x+=440*dt;
    var hit=null,hx=1e9;
    for(var j=0;j<zombies.length;j++){var z=zombies[j];
      if(z.r!==q.r||z.dead||z.x>1275||z.jy<-40)continue;
      if(q.x>=z.x-24&&q.x<=z.x+28&&z.x<hx){hit=z;hx=z.x;}}
    if(hit){
      hurtZombie(hit,q.dmg,q.ice?'ice':'pea');
      var sx=hit.x-18;
      FX.add(q.ice?'fxSplatI':'fxSplat',sx,q.y,{s0:0.5,s1:1.25,life:0.22,rot:rnd(0,360),fade:0.3});
      for(var k=0;k<3;k++)FX.add(q.ice?'fxSnow':'fxLeaf',sx,q.y,{vx:rnd(-90,40),vy:rnd(-130,10),g:520,life:0.4,rot:rnd(0,360),vr:rnd(-400,400),s0:0.65,s1:0.3});
      SFX.splat();killPea(i);continue;
    }
    if(q.x>1300)killPea(i);
  }
}

