function freeZombie(z){var i=zombies.indexOf(z);if(i>=0)zombies.splice(i,1);show(z.dom.g,false);zPool[z.type].push(z.dom);}
function blocker(z){
  var mx=z.x-22,row=grid[z.r],c=Math.floor((mx-GX)/TW);
  for(var cc=c-1;cc<=c+1;cc++){if(cc<0||cc>=COLS)continue;var p=row[cc];if(p&&!p.dead&&p.type!==5&&Math.abs(mx-p.x)<26)return p;}
  return null;
