}
function updZombie(z,dt){
  z.t+=dt;if(z.flash>0)z.flash-=dt;
  if(z.dead){z.deadT+=dt;if(z.deadT>(z.kind==='mow'?1:1.5))freeZombie(z);return;}
  if(z.slow>0)z.slow-=dt;
  var sl=z.slow>0?0.5:1;
  if(z.idle>0){z.idle-=dt;z.ph+=dt*0.9;z.eat=null;return;}
  if(z.vault){
    var v=z.vault;v.t+=dt/0.8;var k=Math.min(1,v.t);
    z.x=lerp(v.x0,v.x1,eio(k));z.jy=-Math.sin(Math.PI*k)*84;
    if(v.t>=1){z.vault=null;z.jy=0;z.spd=ZT[0].spd+1;SFX.thud();
      for(var q=0;q<5;q++)FX.add('fxDust',z.x+rnd(-20,20),z.y-4,{vx:rnd(-60,60),vy:rnd(-40,-10),s0:0.6,s1:1.3,life:0.45,a0:0.8,fade:0.3});}
    return;
  }
  var p=blocker(z);
  if(p&&z.pole){dropPole(z);z.vault={t:0,x0:z.x,x1:p.x-62};SFX.whoosh();return;}
  if(p){z.eat=p;z.chew+=dt*sl;if(z.chew>=0.5){z.chew-=0.5;bite(z,p);}}
  else{
    z.eat=null;
    var sp=z.spd*z.sm*(G.demo?1:G.D.spd)*sl*(z.sprint?2.3:1);
    z.x-=sp*dt;z.ph+=sp*dt*0.105;
    if(z.sprint&&Math.random()<dt*3)FX.add('fxSweat',z.x+8,z.y-122,{vx:rnd(20,60),vy:-60,g:300,life:0.5,s0:1,s1:0.6});
  }
  if(!G.demo){
    if(z.x<MOW_TRIGGER){var m=mowers[z.r];if(m.st===0)fireMower(m);}
    if(z.x<HOUSE_X&&G.state==='playing'&&!G.god)loseGame(z);
  }else if(z.x<520)killZombie(z,'');
}
function bite(z,p){
  SFX.chomp();
  for(var k=0;k<3;k++)FX.add(p.type===4?'fxCrumb':'fxLeaf',p.x+rnd(0,20),p.y-rnd(20,50),{vx:rnd(-40,90),vy:rnd(-150,-40),g:520,life:0.5,rot:rnd(0,360),vr:rnd(-300,300),s0:0.85,s1:0.4,gr:p.y});
  p.flash=0.09;p.hurt=0.55;
  if(G.demo)return;
  p.hp-=25;if(p.hp<=0)killPlant(p);
}
function hurtZombie(z,dmg,kind){
  if(z.dead)return;
  z.flash=0.1;if(kind==='ice')z.slow=6;
  var d=dmg;
  if(z.armor>0){
    var a=Math.min(z.armor,d);z.armor-=a;d-=a;
    if(z.type===2&&kind!=='boom')SFX.clank();
    if(!z.accDmg&&z.armor<z.maxArmor*0.5){z.accDmg=true;setH(z.dom.acc,z.type===1?'zConeD':'zPailD');}
    if(z.armor<=0)dropAcc(z);
  }
  if(d<=0)return;
  z.hp-=d;
  if(!z.armOff&&z.hp<z.maxHp*0.5&&z.hp>0){z.armOff=true;setH(z.dom.armF,ZSKIN[z.type].armS);dropArm(z);}
  if(z.type===3&&!z.sprint&&z.hp<z.maxHp*0.6&&z.hp>0){z.sprint=true;
    for(var k=0;k<4;k++)FX.add('fxPuff',z.x+rnd(10,30),z.y-rnd(4,20),{vx:rnd(40,120),vy:rnd(-30,0),s0:0.6,s1:1.4,life:0.4,a0:0.8,fade:0.2});}
  if(z.hp<=0)killZombie(z,kind);
}
function dropAcc(z){
  if(z.accOff)return;z.accOff=true;
  var id=z.dom.acc._h;setH(z.dom.acc,'none');if(!id||id==='none')return;
  FX.add(id,z.x-5*ZS,z.y+z.jy-86*ZS,{s0:ZS,vx:rnd(40,90),vy:rnd(-230,-160),g:900,vr:rnd(200,380),life:1.3,fade:0.7,gr:z.y-8,bn:0.35});
