}
function dropArm(z){
  FX.add(ZSKIN[z.type].arm,z.x-9*ZS,z.y+z.jy-80*ZS,{s0:ZS,vx:rnd(-30,30),vy:-120,g:900,vr:rnd(-300,-150),life:1.1,fade:0.6,gr:z.y-6,bn:0.3});
