  else if(kind==='mow')for(k=0;k<6;k++)FX.add('fxPuff',z.x+rnd(-20,20),z.y-rnd(0,40),{vx:rnd(40,200),vy:rnd(-120,-20),g:200,s0:0.7,s1:1.6,life:0.5,a0:0.9,fade:0.2});
  else FX.add('fxStar',z.x-8,z.y-130,{vy:-30,vr:180,life:0.8,s0:1.2,s1:0.6});
}
function rZombie(z){
  var d=z.dom;
  setT(d.g,'translate('+f1(z.x)+','+f1(z.y)+') scale('+ZS+')');
  if(z.dead){
    var t=z.deadT,op=1;
    if(z.kind==='mow'){var k=Math.min(1,t/0.12);setT(d.b,'scale('+f2(1+0.35*k)+','+f2(1-0.72*k)+')');op=t<0.3?1:Math.max(0,1-(t-0.3)/0.6);}
    else if(z.kind==='boom'){var k2=Math.min(1,t/1.2);setT(d.b,'translate('+f1(Math.sin(t*40)*(1-k2)*2)+',0) scale(1,'+f2(1-0.5*k2)+')');op=t<0.5?1:Math.max(0,1-(t-0.5)/0.8);}
    else{var k3=Math.min(1,t/0.55);setT(d.b,'rotate('+f1(82*k3*k3)+',8,0)');op=t<0.8?1:Math.max(0,1-(t-0.8)/0.6);}
    setA(d.g,'opacity',f2(op));
    setT(d.legB,'translate(5,-40) rotate(6)');setT(d.legF,'translate(-5,-40) rotate(-4)');
    setT(d.armF,'translate(-9,-80) rotate(30)');setT(d.armB,'translate(9,-82) rotate(20)');
    setT(d.h,'translate(-5,-86) rotate(12)');
    setF(d.g,z.kind==='boom'?'url(#fBurn)':'');
    return;
  }
  var lb,lf,ab,af,hr,by=0,lean,face='zFaceN',s;
  if(z.vault){var vt=Math.min(1,z.vault.t);lean=-25+45*vt;lb=-40;lf=-60;ab=-60;af=-70;hr=-10;by=z.jy;}
  else if(z.eat){var c=Math.sin(z.t*11*(z.slow>0?0.5:1));hr=-6+c*8;af=-26+c*9;ab=-34-c*7;lean=-7;lb=6;lf=-5;face=c>0?'zFaceC':'zFaceN';}
  else if(z.idle>0){s=Math.sin(z.ph);lb=s*6;lf=-s*6;af=-6+s*5;ab=-14+Math.cos(z.ph)*5;hr=Math.sin(z.ph*0.8)*7;lean=-2+s;by=-Math.abs(s)*1.2;}
  else{s=Math.sin(z.ph);var amp=z.sprint?32:18;lb=s*amp;lf=-s*amp;by=-Math.abs(Math.cos(z.ph))*(z.sprint?4:2.4);
    af=-8+Math.sin(z.ph*1.3)*7-(z.sprint?22:0);ab=-16+Math.cos(z.ph*1.3)*7;hr=Math.sin(z.ph*0.7)*5;lean=z.sprint?-12:-3;}
  setH(d.face,face);
  setT(d.b,'translate(0,'+f1(by)+') rotate('+f1(lean)+')');
  setT(d.legB,'translate(5,-40) rotate('+f1(lb)+')');
  setT(d.legF,'translate(-5,-40) rotate('+f1(lf)+')');
  setT(d.armB,'translate(9,-82) rotate('+f1(ab)+')');
  setT(d.armF,'translate(-9,-80) rotate('+f1(af)+')');
  setT(d.h,'translate(-5,-86) rotate('+f1(hr)+')');
  var op=1;if(G.state==='over'&&z===G.intruder)op=clamp((z.x-30)/50,0,1);
  setA(d.g,'opacity',f2(op));
  setF(d.g,z.flash>0?(z.slow>0?'url(#fIceHit)':'url(#fHit)'):(z.slow>0?'url(#fIce)':''));
}

/* ---------- suns ---------- */
function makeSunEl(){var g=E('g',null,L.sun);U(g,'sunGlow');var rays=U(g,'sunRays');U(g,'sunCore');return {g:g,rays:rays};}
function spawnSun(x,y,kind){
  var el=sunFree.pop()||makeSunEl();show(el.g,true);
  var s={el:el,x:x,y:y,kind:kind,st:'fall',t:0,life:0,val:25,rot:Math.random()*360,a:1,sc:1};
  if(kind==='sky'){s.vy=46;s.ty=rnd(GY+60,GY+TH*ROWS-40);s.sx=x;}
  else{s.vy=-200;s.vx=rnd(-45,45);s.ty=y+rnd(46,58);s.g=560;s.sc=0.4;}
  suns.push(s);return s;
}
function freeSun(i){var s=suns[i];show(s.el.g,false);sunFree.push(s.el);suns.splice(i,1);}
function collectSun(s){
  if(s.st==='fly')return false;
  s.st='fly';s.t=0;s.x0=s.x;s.y0=s.y;s.a=1;
  if(G.demo){s.tx=-70;s.ty2=-70;}else{s.tx=SUN_HUD.x;s.ty2=SUN_HUD.y;G.sun+=s.val;G.sunGot+=s.val;}
  SFX.sun();return true;
}
function updSuns(dt){
  for(var i=suns.length-1;i>=0;i--){
    var s=suns[i];s.t+=dt;s.rot+=dt*50;
    if(s.st==='fall'){
      if(s.kind==='sky'){s.y+=s.vy*dt;s.x=s.sx+Math.sin(s.t*1.4)*10;if(s.y>=s.ty){s.y=s.ty;s.st='rest';}}
      else{s.vy+=s.g*dt;s.x+=s.vx*dt;s.y+=s.vy*dt;s.sc=Math.min(1,s.sc+dt*3);if(s.vy>0&&s.y>=s.ty){s.y=s.ty;s.st='rest';}}
    }else if(s.st==='rest'){
      s.life+=dt;
      if((G.demo||G.autoSun)&&s.life>0.7)collectSun(s);
      else if(s.life>9.5)s.st='fade';
    }else if(s.st==='fade'){s.a-=dt*1.6;if(s.a<=0){freeSun(i);continue;}}
    else if(s.st==='fly'){
      var k=Math.min(1,s.t/0.6),e=eio(k);
      s.x=lerp(s.x0,s.tx,e);s.y=lerp(s.y0,s.ty2,e)-Math.sin(k*Math.PI)*50;s.sc=1-0.35*k;
      if(Math.random()<dt*22)FX.add('fxSpark',s.x+rnd(-10,10),s.y+rnd(-10,10),{life:0.3,s0:0.9,s1:0.2,rot:rnd(0,90)});
      if(k>=1){freeSun(i);
        if(!G.demo){G.sunPulse=1;for(var q=0;q<6;q++){var a=q*1.047;CF.add('fxSpark',SUN_HUD.x,SUN_HUD.y,{vx:Math.cos(a)*120,vy:Math.sin(a)*120,life:0.35,s0:1.2,s1:0.3,drag:3});}}
        continue;}
    }
  }
}
function rSun(s){
  var rest=s.st==='rest',bob=rest?Math.sin(s.t*3)*3:0,sc=s.sc*(rest?1+Math.sin(s.t*4)*0.04:1);
  setT(s.el.g,'translate('+f1(s.x)+','+f1(s.y+bob)+') scale('+f2(sc)+')');
  setT(s.el.rays,'rotate('+f1(s.rot%360)+')');
  var blink=rest&&s.life>7.5&&Math.sin(s.life*16)<0?0.45:1;
  setA(s.el.g,'opacity',f2(s.a*blink));
}

/* ---------- mowers ---------- */
function buildMowers(){for(var r=0;r<ROWS;r++){var el=U(RL[r].mow,'mower');mowers.push({r:r,x:MOWER_X,st:0,v:0,el:el,t:0});}}
function resetMowers(){mowers.forEach(function(m){m.st=0;m.x=MOWER_X;m.v=0;m.t=0;show(m.el,true);});}
function mowersLeft(){var n=0;mowers.forEach(function(m){if(m.st===0)n++;});return n;}
function fireMower(m){m.st=1;m.v=60;SFX.mower();G.shake=Math.max(G.shake,4);toast('小推车出动！');}
function updMowers(dt){
  mowers.forEach(function(m){
    if(m.st!==1)return;
    m.t+=dt;m.v=Math.min(600,m.v+1500*dt);m.x+=m.v*dt;
    for(var i=0;i<zombies.length;i++){var z=zombies[i];if(z.r===m.r&&!z.dead&&z.x>m.x-34&&z.x<m.x+50)killZombie(z,'mow');}
    if(Math.random()<dt*40)FX.add('fxGrass',m.x-30,rowY(m.r)-4,{vx:rnd(-160,-60),vy:rnd(-160,-60),g:600,life:0.5,rot:rnd(-30,30),vr:rnd(-200,200),s0:1,s1:0.6});
    if(m.x>1360){m.st=2;show(m.el,false);}
  });
}
function rMower(m){if(m.st===2)return;setT(m.el,'translate('+f1(m.x)+','+rowY(m.r)+')'+(m.st===1?' rotate('+f1(Math.sin(G.t*40)*1.5)+')':''));}

/* ---------- popups ---------- */
function makePop(){var t=Tx(L.fx,0,0,'',{class:'rd ol','font-size':20,'text-anchor':'middle',fill:'#fff36b',stroke:'#5a3412','stroke-width':4});show(t,false);return t;}
function popup(s,x,y,color){var el=popFree.pop()||makePop();setTxt(el,s);setA(el,'fill',color||'#fff36b');show(el,true);pops.push({el:el,x:x,y:y,t:0});}
function updPops(dt){
  for(var i=pops.length-1;i>=0;i--){var p=pops[i];p.t+=dt;
    if(p.t>0.9){show(p.el,false);popFree.push(p.el);pops.splice(i,1);continue;}
    var sc=p.t<0.15?0.5+p.t/0.15*0.7:1.2-Math.min(0.2,p.t-0.15);
    setT(p.el,'translate('+f1(p.x)+','+f1(p.y-p.t*40)+') scale('+f2(sc)+')');
    setA(p.el,'opacity',f2(p.t<0.6?1:1-(p.t-0.6)/0.3));}
}

/* =========================================================
   7. GAME STATE & FLOW
   ========================================================= */
var G={state:'title',diff:1,D:DIFFS[1],t:0,rt:0,runT:0,sun:0,score:0,kills:0,killPts:0,sunGot:0,planted:0,
  wave:0,nextWaveT:0,lastWaveT:0,flagArmed:false,spawnQ:[],sel:-1,shovel:false,cur:{r:2,c:3},kb:false,
  mouse:{x:-99,y:-99,on:false},cd:[0,0,0,0,0,0],ts:1,god:false,noSpawn:false,autoSun:false,demo:true,
  skyT:5,endT:0,shake:0,best:0,newBest:false,helpFrom:'title',groanT:6,bannerT:-1,bannerFinal:false,cdT:0,cdGo:false,
  intruder:null,lastRow:-1,demoT:0,toastT:0,sunPulse:0,pauseFocus:0,endFocus:0,stars:0,confT:0};
function loadBest(){try{var v=parseInt(localStorage.getItem(BEST_KEY),10);G.best=isNaN(v)?0:v;}catch(e){G.best=0;}}
function saveBest(){try{localStorage.setItem(BEST_KEY,String(G.best));}catch(e){}}
function toast(s){setTxt(HUD.toast,s);G.toastT=1.6;}
function cardShake(i){HUD.cards[i].shake=0.35;}
function aliveCount(){var n=0;for(var i=0;i<zombies.length;i++)if(!zombies[i].dead)n++;return n;}
function tileAt(x,y){if(x<GX||x>=GX+COLS*TW||y<GY||y>=GY+ROWS*TH)return null;return {r:Math.floor((y-GY)/TH),c:Math.floor((x-GX)/TW)};}

function clearWorld(){
  var i;
  while(zombies.length)freeZombie(zombies[zombies.length-1]);
  while(plants.length)removePlant(plants[plants.length-1]);
  for(i=peas.length-1;i>=0;i--)killPea(i);
  for(i=suns.length-1;i>=0;i--)freeSun(i);
  FX.clear();LFX.clear();CF.clear();
  for(i=0;i<pops.length;i++){show(pops[i].el,false);popFree.push(pops[i].el);}pops.length=0;
  G.spawnQ.length=0;G.sel=-1;G.shovel=false;G.intruder=null;G.bannerT=-1;G.shake=0;G.toastT=0;
}
function hideOverlays(){[TI.g,HP.g,PS.g,OV.g,RS.g,CD.g,BN.g].forEach(function(g){show(g,false);});}
function setupDemo(){
  G.demo=true;G.D=DIFFS[1];G.t=0;G.skyT=2;G.demoT=5;
  [[0,0,0],[1,0,1],[0,1,0],[2,1,1],[3,2,0],[4,2,1],[0,3,0],[1,3,1],[0,4,0],[3,4,1]].forEach(function(q){
    var p=addPlant(q[0],q[1],q[2]);if(p){p.pop=1;if(q[0]===0)p.timer=rnd(1.5,7);}});
  addZombie(4,0,1196,{sm:0.5});addZombie(0,1,968,{sm:0.5});addZombie(2,2,1122,{sm:0.45});addZombie(1,3,930,{sm:0.5});addZombie(3,4,1046,{sm:0.5});
  resetMowers();
  var s=spawnSun(700,40,'sky');s.ty=300;
}
function updDemo(dt){
  G.demoT-=dt;
  if(G.demoT<=0){G.demoT=rnd(3.5,6);if(aliveCount()<6)addZombie(irnd(0,3),irnd(0,4),SPAWN_X,{sm:0.5});}
}
function goTitle(){
  clearWorld();hideOverlays();show(L.hud,false);
  setupDemo();G.state='title';show(TI.g,true);TI.focus=1;refreshTitle();
  musicOn(true);
}
function setDiff(k){if(G.diff!==k){G.diff=k;SFX.click();}refreshTitle();}
function startRun(d,skip){
  auInit();
  G.diff=clamp(d|0,0,2);G.D=DIFFS[G.diff];
  clearWorld();G.demo=false;
  G.t=0;G.runT=0;G.sun=G.D.sun;G.kills=0;G.killPts=0;G.sunGot=0;G.planted=0;G.score=0;G.newBest=false;
  for(var i=0;i<6;i++)G.cd[i]=PT[i].cd*PT[i].start;
  G.skyT=4;G.wave=0;G.lastWaveT=0;G.nextWaveT=G.D.first;G.flagArmed=false;G.groanT=9;G.lastRow=-1;
  resetMowers();buildFlags();
  setTxt(HUD.diffTxt,G.D.name);setA(HUD.diffBadge,'fill',G.D.color);
  G.cur={r:2,c:3};G.kb=false;G.endFocus=0;G.pauseFocus=0;
  hideOverlays();show(L.hud,true);
  G.cdT=0;G.cdGo=false;
  if(skip){G.state='playing';}
  else{G.state='countdown';mowers.forEach(function(m){m.x=-90;});SFX.tick();}
  musicOn(true);
}
function pauseGame(){if(G.state!=='playing')return;G.state='paused';G.pauseFocus=0;show(PS.g,true);musicOn(false);SFX.click();}
function resumeGame(){if(G.state!=='paused')return;G.state='playing';show(PS.g,false);musicOn(true);SFX.click();}
function openHelp(){
  var s=G.state;if(s!=='title'&&s!=='paused'&&s!=='playing')return;
  G.helpFrom=s;if(s==='playing')musicOn(false);
  G.state='help';show(HP.g,true);show(PS.g,false);if(s==='title')show(TI.g,false);SFX.click();
}
function closeHelp(){
  if(G.state!=='help')return;show(HP.g,false);G.state=G.helpFrom;
  if(G.state==='playing')musicOn(true);else if(G.state==='paused')show(PS.g,true);else if(G.state==='title')show(TI.g,true);
  SFX.click();
}
function calcScore(win){var s=G.killPts+G.sunGot;if(win)s+=2000+mowersLeft()*500;return Math.round(s*G.D.mult);}
function finishStats(win){
  G.score=calcScore(win);G.newBest=G.score>G.best;
  if(G.newBest){G.best=G.score;saveBest();}
}
function loseGame(z){
  if(G.state!=='playing')return;
  G.state='over';G.endT=0;G.intruder=z;G.sel=-1;G.shovel=false;G.endFocus=0;
  finishStats(false);
  setTxt(OV.sub,G.D.name+'难度 · 坚持到第 '+Math.max(1,G.wave)+' / '+G.D.waves+' 波');
  var v=OV.v;setTxt(v[0],G.score);setTxt(v[1],'第 '+Math.max(1,G.wave)+' 波');setTxt(v[2],G.kills);setTxt(v[3],G.sunGot);setTxt(v[4],G.planted);setTxt(v[5],fmtTime(G.runT));
  setTxt(OV.best,'最高分 '+G.best);show(OV.nb.g,G.newBest);
  show(OV.g,true);show(OV.panel,false);
  musicOn(false);SFX.lose();G.shake=8;
}
function winGame(){
  if(G.state!=='playing')return;
  G.state='results';G.endT=0;G.sel=-1;G.shovel=false;G.endFocus=0;G.confT=0;
  var ml=mowersLeft();
  finishStats(true);
  G.stars=ml===5?3:ml>=3?2:1;
  var v=RS.v;setTxt(v[0],G.score);setTxt(v[1],G.kills);setTxt(v[2],G.sunGot);setTxt(v[3],ml+' / 5');setTxt(v[4],G.planted);setTxt(v[5],fmtTime(G.runT));
  setTxt(RS.best,G.D.name+'难度 · 最高分 '+G.best);show(RS.nb.g,G.newBest);
  RS.stars.forEach(function(s){setA(s,'fill','#e0d2b0');setA(s,'stroke','#9a7a4a');});
  show(RS.g,true);show(RS.panel,false);
  musicOn(false);SFX.win();
}

/* ---------- waves ---------- */
function isFlag(w){return G.D.flags.indexOf(w)>=0;}
function pickRow(){var r,n=0;do{r=irnd(0,ROWS-1);n++;}while(r===G.lastRow&&n<4);G.lastRow=r;return r;}
function showBanner(final){
  G.bannerT=0;G.bannerFinal=final;
  setTxt(BN.t,final?'最后一波！守住家门！':'僵尸大游行来啦！');
  setTxt(BN.s,final?'FINAL WAVE':'ZOMBIE PARADE INCOMING');
  SFX.horn();G.shake=Math.max(G.shake,3);
}
function launchWave(){
  var D=G.D,w=G.wave+1,flag=isFlag(w),t,i;
  G.flagArmed=false;
  var budget=w===1?D.b0:Math.round((D.b0+(w-1)*D.bs)*(flag?2.2:1)+(flag?2:0));
  var avail=[];for(t=0;t<5;t++)if(w>=D.unlock[t])avail.push(t);
  var list=[];if(flag)list.push(0,0);
  var guard=0;
  while(budget>0&&guard++<200){
    var opts=avail.filter(function(q){return ZT[q].cost<=budget;});if(!opts.length)break;
    var tot=0,wts=opts.map(function(q){var x=[5,4,1+w*0.3,2.6,2.2][q];tot+=x;return x;});
    var r=Math.random()*tot,k=0;while(k<wts.length-1&&r>wts[k]){r-=wts[k];k++;}
    list.push(opts[k]);budget-=ZT[opts[k]].cost;
  }
  var spread=flag?8:Math.min(6,1+list.length*0.9);
  for(i=0;i<list.length;i++)G.spawnQ.push({t:G.t+(i===0?0:rnd(0.4,spread)),type:list[i],row:pickRow()});
  G.wave=w;G.lastWaveT=G.t;G.nextWaveT=G.t+D.gap+(flag?8:0);
  if(w===1)toast('僵尸来啦！小心！');
  SFX.groan();
}
function updWaves(){
  var D=G.D,i;
  for(i=G.spawnQ.length-1;i>=0;i--){var s=G.spawnQ[i];if(G.t>=s.t){addZombie(s.type,s.row,SPAWN_X+rnd(0,50));G.spawnQ.splice(i,1);}}
  if(G.noSpawn)return;
  if(G.wave>=D.waves){if(G.spawnQ.length===0&&aliveCount()===0)winGame();return;}
  if(G.flagArmed){if(G.t>=G.nextWaveT)launchWave();return;}
  var early=G.wave>0&&G.spawnQ.length===0&&aliveCount()===0&&G.t-G.lastWaveT>6;
  if(G.t>=G.nextWaveT||early){
    var w=G.wave+1;
    if(isFlag(w)){G.flagArmed=true;showBanner(w===D.waves);G.nextWaveT=G.t+3.4;return;}
    launchWave();
  }
}
function progress(){var N=G.D.waves;if(G.wave>=N)return 1;var span=Math.max(0.01,G.nextWaveT-G.lastWaveT),f=G.flagArmed?1:clamp((G.t-G.lastWaveT)/span,0,1);return (G.wave+f)/N;}

/* ---------- player actions ---------- */
function selectCard(i){
  if(G.state!=='playing'||i<0||i>5)return;
  if(G.sel===i){G.sel=-1;SFX.click();return;}
  var P=PT[i];
  if(G.cd[i]>0){toast('卡片冷却中…');SFX.buzz();cardShake(i);return;}
  if(G.sun<P.cost){toast('阳光不够哦！');SFX.buzz();cardShake(i);return;}
  G.sel=i;G.shovel=false;SFX.pop();
}
function toggleShovel(){if(G.state!=='playing')return;G.shovel=!G.shovel;G.sel=-1;SFX.click();}
function cancelSel(){if(G.sel>=0||G.shovel){G.sel=-1;G.shovel=false;SFX.click();return true;}return false;}
function tryPlant(r,c){
  var i=G.sel;if(i<0)return false;var P=PT[i];
  if(grid[r][c]){toast('这里已经有植物了');SFX.buzz();FX.add('fxX',colX(c),GY+r*TH+TH/2,{life:0.5,s0:1.2,s1:0.9,fade:0.4});return false;}
  if(G.sun<P.cost){toast('阳光不够哦！');SFX.buzz();cardShake(i);return false;}
  if(G.cd[i]>0){toast('卡片冷却中…');SFX.buzz();return false;}
  var p=addPlant(i,r,c);if(!p)return false;
  G.sun-=P.cost;G.cd[i]=P.cd;G.planted++;plantJuice(p);G.sel=-1;
  return true;
}
function tryShovel(r,c){
  var p=grid[r][c];if(!p){toast('这里没有植物');SFX.buzz();return false;}
  for(var k=0;k<6;k++)FX.add('fxDust',p.x+rnd(-24,24),p.y-rnd(0,10),{vx:rnd(-80,80),vy:rnd(-70,-20),s0:0.6,s1:1.4,life:0.5,a0:0.9,fade:0.3});
  FX.add('fxPuff',p.x,p.y-30,{s0:0.8,s1:2,life:0.35,a0:0.8,fade:0.2});
  SFX.shovel();removePlant(p);G.shovel=false;return true;
}

/* ---------- update ---------- */
function updSky(dt){G.skyT-=dt;if(G.skyT<=0){G.skyT=(G.demo?4.5:G.D.sky)*rnd(0.85,1.15);spawnSun(rnd(GX+40,GX+TW*COLS-40),-30,'sky');}}
function simStep(dt){
  var i;G.t+=dt;
  if(G.state==='playing'){
    G.runT+=dt;updWaves();
    for(i=0;i<6;i++)if(G.cd[i]>0)G.cd[i]=Math.max(0,G.cd[i]-dt);
    G.groanT-=dt;if(G.groanT<=0){G.groanT=rnd(6,12);if(aliveCount()>0)SFX.groan();}
    if(G.bannerT>=0){G.bannerT+=dt;if(G.bannerT>3.3)G.bannerT=-1;}
  }else updDemo(dt);
  updSky(dt);
  for(i=plants.length-1;i>=0;i--)if(plants[i])updPlant(plants[i],dt);
  for(i=zombies.length-1;i>=0;i--)if(zombies[i])updZombie(zombies[i],dt);
  updPeas(dt);updSuns(dt);updMowers(dt);FX.update(dt);LFX.update(dt);updPops(dt);
  if(G.state==='playing')G.score=Math.round((G.killPts+G.sunGot)*G.D.mult);
}
function update(dt){
  var s=G.state,i;
  if(s==='playing'||s==='title')simStep(dt);
  else if(s==='countdown'){
    G.cdT+=dt;G.t+=dt;
    mowers.forEach(function(m){m.x=lerp(-90,MOWER_X,eob(clamp((G.cdT-0.15-m.r*0.1)/0.6,0,1)));});
    for(i=0;i<plants.length;i++)plants[i].t+=dt;
    if(!G.cdGo&&G.cdT>=1){G.cdGo=true;SFX.go();}
    if(G.cdT>=2.3){G.state='playing';mowers.forEach(function(m){m.x=MOWER_X;});}
    FX.update(dt);
  }else if(s==='over'||s==='results'){
    G.endT+=dt;G.t+=dt;
    var z=G.intruder;
    if(s==='over'&&z&&!z.dead&&z.x>20){z.eat=null;z.x-=20*dt;z.ph+=20*dt*0.105;z.t+=dt;}
    for(i=zombies.length-1;i>=0;i--)if(zombies[i]&&zombies[i].dead)updZombie(zombies[i],dt);
    updSuns(dt);FX.update(dt);LFX.update(dt);CF.update(dt);updPops(dt);updMowers(dt);
    if(s==='results'&&G.endT>0.9&&G.endT<3.2){G.confT-=dt;if(G.confT<=0){G.confT=0.35;confetti(18);}}
  }
}
function confetti(n){
  var cols=['#e8453a','#ffd23a','#6cc644','#4a9fe8','#ff86b4','#ff9a3c'];
  for(var i=0;i<n;i++)CF.add('fxConf',rnd(360,920),rnd(60,120),{color:cols[i%6],vx:rnd(-120,120),vy:rnd(-260,-60),g:420,rot:rnd(0,360),vr:rnd(-500,500),life:rnd(1.8,2.6),s0:rnd(0.8,1.3),sy:rnd(0.5,1),fade:0.75,drag:0.6});
}

/* ---------- render ---------- */
var GH={};
function buildGhost(){
  GH.tile=E('rect',{x:0,y:0,width:TW-6,height:TH-6,rx:10,fill:'#ffffff','fill-opacity':.18,stroke:'#ffffff','stroke-opacity':.9,'stroke-width':3,'stroke-dasharray':'10 6'},L.lawnFx);
  GH.ghost=U(L.ghost,'none',{opacity:.5});GH.cur=U(L.ghost,'none');
  show(GH.tile,false);show(GH.ghost,false);show(GH.cur,false);
}
function rGhost(){
  var on=G.state==='playing',tile=null;
  if(on){if(G.kb)tile=G.cur;else if(G.mouse.on)tile=tileAt(G.mouse.x,G.mouse.y);}
  var active=on&&(G.sel>=0||G.shovel||G.kb);
  if(active&&tile){
    show(GH.tile,true);setT(GH.tile,'translate('+(GX+tile.c*TW+3)+','+(GY+tile.r*TH+3)+')');
    var occ=!!grid[tile.r][tile.c],col=G.sel>=0?(occ?'#ff6a5a':'#ffffff'):G.shovel?(occ?'#ffb040':'#ffffff'):'#fff36b';
    setA(GH.tile,'stroke',col);setA(GH.tile,'fill',col);setA(GH.tile,'stroke-dashoffset',f1((G.rt*30)%16));
  }else show(GH.tile,false);
  if(active&&tile&&G.sel>=0&&!grid[tile.r][tile.c]){show(GH.ghost,true);setH(GH.ghost,'ico_'+PT[G.sel].id);setT(GH.ghost,'translate('+colX(tile.c)+','+rowY(tile.r)+')');}
  else show(GH.ghost,false);
  if(on&&!G.kb&&G.mouse.on&&(G.sel>=0||G.shovel)){
    show(GH.cur,true);
    if(G.sel>=0){setH(GH.cur,'ico_'+PT[G.sel].id);setT(GH.cur,'translate('+f1(G.mouse.x)+','+f1(G.mouse.y+34)+') scale(.85)');}
    else{setH(GH.cur,'icoShovel');setT(GH.cur,'translate('+f1(G.mouse.x+14)+','+f1(G.mouse.y-8)+') rotate(-35) scale(.85)');}
  }else show(GH.cur,false);
}
function rHud(){
  var s=G.state;if(s==='title')return;
  var i,k;
  setTxt(HUD.sunTxt,G.sun);
  setT(HUD.sunG,'translate(54,38) scale('+f2(1+G.sunPulse*0.22)+')');
  setT(HUD.sunRays,'rotate('+f1((G.rt*30)%360)+') scale(.88)');
  for(i=0;i<6;i++){var c=HUD.cards[i],P=PT[i];k=G.cd[i]>0?G.cd[i]/P.cd:0;
    setA(c.cdr,'height',f1(84*k));var poor=G.sun<P.cost;show(c.grey,poor||k>0);setA(c.cost,'fill',poor?'#d03020':'#5a3412');
    var on=G.sel===i;show(c.sel,on);c.lift+=((on?1:0)-c.lift)*0.3;
    setT(c.n,'translate('+f1(c.shake>0?Math.sin(c.shake*60)*4:0)+','+f1(-c.lift*7)+')');}
  show(HUD.shovelSel,G.shovel);setA(HUD.shovelIco,'opacity',G.shovel?'0.35':'1');
  setTxt(HUD.scoreTxt,G.score);
  var pr=progress();setA(HUD.barFill,'width',f1(Math.max(0,208*pr)));
  setT(HUD.zHead,'translate('+f1(1044+208*pr)+',697)');
  setTxt(HUD.waveTxt,G.wave===0?'准备中':'第'+G.wave+'/'+G.D.waves+'波');
  HUD.flags.forEach(function(f){f.up+=((G.wave>=f.w?1:0)-f.up)*0.15;setT(f.el,'translate('+f1(Math.min(f.x-2,1240))+','+f1(690-f.up*7)+') scale(.8)');});
  setA(HUD.toast,'opacity',f2(G.toastT>0?Math.min(1,G.toastT/0.3):0));
  if(s==='countdown'){k=eo(clamp(G.cdT/0.55,0,1));setT(HUD.tray,'translate(0,'+f1(-112*(1-k))+')');setT(HUD.tr,'translate(0,'+f1(-70*(1-k))+')');setT(HUD.prog,'translate(0,'+f1(60*(1-k))+')');}
  else{setT(HUD.tray,'');setT(HUD.tr,'');setT(HUD.prog,'');}
}
function ringOp(f,h){return f?f2(0.6+Math.sin(G.rt*6)*0.4):(h?0.6:0);}
function btnScale(b,s){setT(b.g,'translate('+b.x+','+b.y+') translate('+(b.w/2)+','+(b.h/2)+') scale('+f2(s)+') translate('+(-b.w/2)+','+(-b.h/2)+')');}
function panelIn(p,k,cy){if(k<=0){show(p,false);return;}show(p,true);setT(p,'translate(640,'+cy+') scale('+f2(eob(k))+') translate(-640,'+(-cy)+')');}
function rOverlays(){
  var s=G.state,rt=G.rt,k;
  if(s==='title'){
    TI.chars.forEach(function(c,i){setT(c.g,'translate(0,'+f1(Math.sin(rt*2.2+i*0.8)*4)+') rotate('+f1(Math.sin(rt*1.6+i)*2.5)+','+c.x+',96)');});
    TI.diff.forEach(function(b,i){setA(b.ring,'opacity',ringOp(TI.focus===0&&i===G.diff,b.hov));});
    setA(TI.start.ring,'opacity',ringOp(TI.focus===1,TI.start.hov));setA(TI.help.ring,'opacity',ringOp(TI.focus===2,TI.help.hov));
    btnScale(TI.start,1+Math.sin(rt*4)*0.025);
  }else if(s==='help')setA(HP.close.ring,'opacity',ringOp(true,0));
  else if(s==='paused')PS.b.forEach(function(b,i){setA(b.ring,'opacity',ringOp(G.pauseFocus===i,b.hov));});
  else if(s==='over'){
    setA(OV.dim,'opacity',f2(0.5*clamp(G.endT/1.2,0,1)));
    k=clamp((G.endT-1.2)/0.45,0,1);panelIn(OV.panel,k,356);
    OV.b.forEach(function(b,i){setA(b.ring,'opacity',ringOp(G.endFocus===i,b.hov));});
    poseZombie(OV.z,462,492,1.02,{af:-40+Math.sin(rt*6)*22,ab:-18,hr:Math.sin(rt*3)*6,lb:8,lf:-8});
    setT(OV.nb.n,'rotate(-8) scale('+f2(1+Math.sin(rt*5)*0.06)+')');
  }else if(s==='results'){
    k=clamp((G.endT-0.8)/0.45,0,1);panelIn(RS.panel,k,358);
    setT(RS.burst,'translate(640,190) rotate('+f1((rt*18)%360)+')');
    setT(RS.trophy,'translate(640,'+f1(240+Math.sin(rt*2.5)*4)+') scale(1.25)');
    RS.stars.forEach(function(st,i){var on=i<G.stars&&G.endT>1.4+i*0.25,kk=clamp((G.endT-1.4-i*0.25)/0.3,0,1);
      if(on){setA(st,'fill','#ffd23a');setA(st,'stroke','#b87010');}
      setT(st,'translate('+(592+i*48)+',330) scale('+f2(on?0.6+0.4*eob(kk):1)+')');});
    RS.b.forEach(function(b,i){setA(b.ring,'opacity',ringOp(G.endFocus===i,b.hov));});
    setT(RS.nb.n,'rotate(-8) scale('+f2(1+Math.sin(rt*5)*0.06)+')');
  }
  if(G.bannerT>=0&&(s==='playing'||s==='paused'||s==='help')){
    var t=G.bannerT;show(BN.g,true);
    var sc=t<0.35?lerp(1.8,1,eob(t/0.35)):1,a=t<0.2?t/0.2:t>2.9?Math.max(0,1-(t-2.9)/0.4):1;
    setT(BN.g,'translate('+f1(640+(t<0.9?Math.sin(t*45)*4*(0.9-t):0))+',330) scale('+f2(sc)+')');setA(BN.g,'opacity',f2(a));
  }else show(BN.g,false);
  if(s==='countdown'){
    show(CD.g,true);var ct=G.cdT,first=ct<1,kk2=first?ct:ct-1;
    setTxt(CD.t,first?'准备好了吗？':'开始守护！');setTxt(CD.s,first?'':'收集阳光 · 种下植物');
    setT(CD.g,'translate(640,380) scale('+f2(kk2<0.25?eob(kk2/0.25):1)+')');
    setA(CD.g,'opacity',f2(ct>1.9?Math.max(0,1-(ct-1.9)/0.4):1));
  }else show(CD.g,false);
}
function render(){
  var i;
  setT(L.world,G.shake>0.2?'translate('+f1(rnd(-G.shake,G.shake))+','+f1(rnd(-G.shake,G.shake)*0.7)+')':'');
  for(i=0;i<clouds.length;i++){var c=clouds[i];setT(c.g,'translate('+f1(c.x)+','+c.y+') scale('+c.s+')');}
  for(i=0;i<plants.length;i++)rPlant(plants[i]);
  for(i=0;i<zombies.length;i++)rZombie(zombies[i]);
  for(i=0;i<peas.length;i++){var q=peas[i];setT(q.el,'translate('+f1(q.x)+','+q.y+')');}
  for(i=0;i<suns.length;i++)rSun(suns[i]);
  for(i=0;i<mowers.length;i++)rMower(mowers[i]);
  FX.render();LFX.render();CF.render();
  rHud();rGhost();rOverlays();
}
function uiUpdate(dt){
  if(G.shake>0)G.shake=Math.max(0,G.shake-dt*28);
  if(G.toastT>0)G.toastT-=dt;
  if(G.sunPulse>0)G.sunPulse=Math.max(0,G.sunPulse-dt*4);
  for(var i=0;i<6;i++){var c=HUD.cards[i];if(c.shake>0)c.shake=Math.max(0,c.shake-dt);}
  for(i=0;i<clouds.length;i++){var cl=clouds[i];cl.x+=cl.v*dt;if(cl.x>1150)cl.x=-90;}
}

/* =========================================================
   8. INPUT
   ========================================================= */
function toView(e){
  try{var p=root.createSVGPoint();p.x=e.clientX;p.y=e.clientY;var m=root.getScreenCTM();if(!m)return {x:-99,y:-99};var q=p.matrixTransform(m.inverse());return {x:q.x,y:q.y};}
  catch(err){return {x:-99,y:-99};}
}
function hit(b,x,y){return x>=b.x&&x<=b.x+b.w&&y>=b.y&&y<=b.y+b.h;}
function screenBtns(){
  var s=G.state;
  if(s==='title')return BTNS.title;if(s==='help')return BTNS.help;if(s==='paused')return BTNS.paused;
  if(s==='over')return G.endT>1.3?BTNS.over:[];if(s==='results')return G.endT>1.0?BTNS.results:[];
  return [];
}
function pointAt(x,y,button){
  var i,bs;
  G.mouse.x=x;G.mouse.y=y;G.mouse.on=true;G.kb=false;
  if(button===2){cancelSel();return;}
  for(i=0;i<BTNS.glob.length;i++)if(hit(BTNS.glob[i],x,y)){BTNS.glob[i].act();return;}
  bs=screenBtns();for(i=0;i<bs.length;i++)if(hit(bs[i],x,y)){SFX.click();bs[i].act();return;}
  if(G.state==='playing')fieldDown(x,y);
}
function fieldDown(x,y){
  var i;
  for(i=0;i<BTNS.hud.length;i++)if(hit(BTNS.hud[i],x,y)){BTNS.hud[i].act();return;}
  for(i=0;i<6;i++){var c=HUD.cards[i];if(x>=c.x&&x<=c.x+CARD_W&&y>=c.y-4&&y<=c.y+CARD_H){selectCard(i);return;}}
  if(hit(SHOVEL,x,y)){toggleShovel();return;}
  var best=null,bd=42*42;
  for(i=suns.length-1;i>=0;i--){var s=suns[i];if(s.st==='fly')continue;var dx=s.x-x,dy=s.y-y,d=dx*dx+dy*dy;if(d<bd){bd=d;best=s;}}
  if(best){collectSun(best);return;}
  if(y<104&&x<640)return;
  var t=tileAt(x,y);
  if(t){if(G.sel>=0)tryPlant(t.r,t.c);else if(G.shovel)tryShovel(t.r,t.c);}
  else cancelSel();
}
root.addEventListener('pointerdown',function(e){
  try{window.focus();}catch(err){}
  auInit();
  var p=toView(e);pointAt(p.x,p.y,e.button);
  if(e.button===2)e.preventDefault();
});
root.addEventListener('pointermove',function(e){
  var p=toView(e);G.mouse.x=p.x;G.mouse.y=p.y;G.mouse.on=true;G.kb=false;
  var bs=screenBtns(),over=false,i;
  for(i=0;i<bs.length;i++){bs[i].hov=hit(bs[i],p.x,p.y)?1:0;if(bs[i].hov)over=true;}
  for(i=0;i<BTNS.glob.length;i++)if(hit(BTNS.glob[i],p.x,p.y))over=true;
  if(G.state==='playing'){
    for(i=0;i<6;i++){var c=HUD.cards[i];if(p.x>=c.x&&p.x<=c.x+CARD_W&&p.y>=c.y&&p.y<=c.y+CARD_H)over=true;}
    if(hit(SHOVEL,p.x,p.y)||hit(BTNS.hud[0],p.x,p.y))over=true;
    for(i=0;i<suns.length;i++){var s=suns[i],dx=s.x-p.x,dy=s.y-p.y;if(dx*dx+dy*dy<42*42)over=true;}
  }
  var cur=over?'pointer':'default';if(root.style.cursor!==cur)root.style.cursor=cur;
});
root.addEventListener('pointerleave',function(){G.mouse.on=false;});
root.addEventListener('contextmenu',function(e){e.preventDefault();});
var USED={Space:1,Enter:1,NumpadEnter:1,Escape:1,ArrowUp:1,ArrowDown:1,ArrowLeft:1,ArrowRight:1,KeyP:1,KeyH:1,KeyM:1,KeyS:1,KeyR:1,KeyQ:1,
  Digit1:1,Digit2:1,Digit3:1,Digit4:1,Digit5:1,Digit6:1,Numpad1:1,Numpad2:1,Numpad3:1,Numpad4:1,Numpad5:1,Numpad6:1};
function digit(k){var m=/^(?:Digit|Numpad)([1-9])$/.exec(k);return m?+m[1]:0;}
function isOk(k){return k==='Enter'||k==='Space'||k==='NumpadEnter';}
window.addEventListener('keydown',function(e){
  var k=e.code;
  if(USED[k])e.preventDefault();
  auInit();
  if(e.repeat&&k.indexOf('Arrow')!==0)return;
  if(k==='KeyM'){setMute(!AU.muted);return;}
  var s=G.state;
  if(s==='title')keyTitle(k);else if(s==='help'){if(isOk(k)||k==='Escape'||k==='KeyH')closeHelp();}
  else if(s==='playing')keyPlay(k);else if(s==='paused')keyPause(k);else if(s==='over'||s==='results')keyEnd(k);
});
function keyTitle(k){
  var n=digit(k);
  if(k==='ArrowLeft')setDiff((G.diff+2)%3);else if(k==='ArrowRight')setDiff((G.diff+1)%3);
  else if(n>=1&&n<=3)setDiff(n-1);
  else if(k==='ArrowUp'){TI.focus=(TI.focus+2)%3;SFX.tick();}else if(k==='ArrowDown'){TI.focus=(TI.focus+1)%3;SFX.tick();}
  else if(isOk(k)){if(TI.focus===2)openHelp();else startRun(G.diff);}
  else if(k==='KeyH')openHelp();
}
function keyPlay(k){
  var n=digit(k);
  if(n>=1&&n<=6){selectCard(n-1);return;}
  if(k==='KeyS'){toggleShovel();return;}
  if(k==='KeyP'){pauseGame();return;}
  if(k==='KeyH'){openHelp();return;}
  if(k==='Escape'){if(!cancelSel())pauseGame();return;}
  if(k.indexOf('Arrow')===0){
    if(!G.kb){G.kb=true;var t=G.mouse.on?tileAt(G.mouse.x,G.mouse.y):null;if(t)G.cur=t;return;}
    if(k==='ArrowLeft')G.cur.c=Math.max(0,G.cur.c-1);else if(k==='ArrowRight')G.cur.c=Math.min(COLS-1,G.cur.c+1);
    else if(k==='ArrowUp')G.cur.r=Math.max(0,G.cur.r-1);else G.cur.r=Math.min(ROWS-1,G.cur.r+1);
    return;
  }
  if(isOk(k)){G.kb=true;kbAct();}
}
function kbAct(){
  var r=G.cur.r,c=G.cur.c,cx=colX(c),cy=GY+r*TH+TH/2,got=false;
  for(var i=suns.length-1;i>=0;i--){var s=suns[i];if(s.st!=='fly'&&Math.abs(s.x-cx)<TW*0.62&&Math.abs(s.y-cy)<TH*0.62){collectSun(s);got=true;}}
  if(G.sel>=0)tryPlant(r,c);else if(G.shovel)tryShovel(r,c);else if(!got)toast('先按 1–6 选择植物卡');
}
function keyPause(k){
  if(k==='KeyP'||k==='Escape')resumeGame();else if(k==='KeyR')startRun(G.diff);else if(k==='KeyQ')goTitle();else if(k==='KeyH')openHelp();
  else if(k==='ArrowUp'){G.pauseFocus=(G.pauseFocus+2)%3;SFX.tick();}else if(k==='ArrowDown'){G.pauseFocus=(G.pauseFocus+1)%3;SFX.tick();}
  else if(isOk(k))PS.b[G.pauseFocus].act();
}
function keyEnd(k){
  var ready=G.state==='over'?G.endT>1.3:G.endT>1.0;if(!ready)return;
  var b=G.state==='over'?OV.b:RS.b;
  if(isOk(k))b[G.endFocus].act();else if(k==='Escape'||k==='KeyQ')goTitle();else if(k==='KeyR')startRun(G.diff);
  else if(k==='ArrowLeft'||k==='ArrowRight'||k==='ArrowUp'||k==='ArrowDown'){G.endFocus=1-G.endFocus;SFX.tick();}
}
window.addEventListener('blur',function(){if(G.state==='playing')pauseGame();});
document.addEventListener('visibilitychange',function(){if(document.hidden&&G.state==='playing')pauseGame();});

/* =========================================================
   9. MAIN LOOP
   ========================================================= */
var lastT=0,frameCount=0;
function frame(ts){
  requestAnimationFrame(frame);
  if(!lastT)lastT=ts;
  var dt=(ts-lastT)/1000;lastT=ts;if(dt>1/30)dt=1/30;if(dt<0)dt=0;
  G.rt+=dt;frameCount++;
  var sc=G.ts,n=Math.max(1,Math.ceil(sc)),sub=dt*sc/n;
  for(var i=0;i<n;i++)update(sub);
  uiUpdate(dt);render();musicTick();
}

/* =========================================================
   10. TEST HOOK & DEBUG
   ========================================================= */
function pIdx(t){return typeof t==='string'?PT.map(function(p){return p.id;}).indexOf(t):t;}
function zIdx(t){return typeof t==='string'?ZT.map(function(z){return z.id;}).indexOf(t):t;}
window.__GAME__={
  get state(){return G.state;},
  get score(){return G.score;},
  start:function(d){startRun(d==null?G.diff:d);},
  debug:{
    skipIntro:function(){if(G.state==='countdown'){G.state='playing';mowers.forEach(function(m){m.x=MOWER_X;});}return G.state;},
    addSun:function(n){G.sun+=n==null?1000:n;return G.sun;},
    plant:function(t,r,c){var p=addPlant(pIdx(t),r,c);if(p){G.planted++;plantJuice(p);}return !!p;},
    spawn:function(t,r,x){var z=addZombie(zIdx(t),r==null?irnd(0,4):r,x==null?SPAWN_X:x);return zombies.length;},
    speed:function(s){G.ts=clamp(+s||1,0.1,8);return G.ts;},
    ff:function(sec){var n=Math.round((sec||10)*30);for(var i=0;i<n;i++)update(1/30);render();return G.state;},
    win:function(){if(G.state!=='playing')return G.state;zombies.forEach(function(z){if(!z.dead)killZombie(z,'');});G.spawnQ.length=0;G.wave=G.D.waves;winGame();return G.state;},
    lose:function(){if(G.state!=='playing')return G.state;var z=null;zombies.forEach(function(q){if(!q.dead&&!z)z=q;});if(!z){z=addZombie(0,2,HOUSE_X+30);}z.x=HOUSE_X-2;loseGame(z);return G.state;},
    wave:function(n){G.wave=clamp((n|0)-1,0,G.D.waves-1);G.flagArmed=false;G.nextWaveT=G.t;return G.wave;},
    god:function(v){G.god=v!==false;return G.god;},
    noSpawn:function(v){G.noSpawn=v!==false;return G.noSpawn;},
    autoSun:function(v){G.autoSun=v!==false;return G.autoSun;},
    select:function(i){selectCard(i);return G.sel;},
    tap:function(x,y,b){pointAt(x,y,b||0);return G.state;},
    key:function(code){var ev=new KeyboardEvent('keydown',{code:code,bubbles:true});window.dispatchEvent(ev);return G.state;},
    stress:function(nz){
      nz=nz||40;G.god=true;G.noSpawn=true;
      for(var r=0;r<ROWS;r++)for(var c=0;c<5;c++)if(!grid[r][c])addPlant(c===4?4:c===0?0:[1,2,3][(r+c)%3],r,c);
      for(var i=0;i<nz;i++)addZombie(i%5,i%ROWS,640+(i*53)%620);
      return aliveCount();
    },
    info:function(){return {state:G.state,t:+G.t.toFixed(1),diff:G.diff,sun:G.sun,wave:G.wave,waves:G.D.waves,alive:aliveCount(),zAll:zombies.length,
      plants:plants.length,peas:peas.length,suns:suns.length,fx:FX.act.length,mowers:mowersLeft(),score:G.score,kills:G.kills,sel:G.sel,
      dom:document.getElementsByTagName('*').length,frames:frameCount};},
    suns:function(){return suns.map(function(s){return {x:Math.round(s.x),y:Math.round(s.y),st:s.st};});},
    grid:function(){return grid.map(function(row){return row.map(function(p){return p?PT[p.type].id+':'+Math.round(p.hp):'.';}).join(' ');});}
  }
};

/* ---------- init ---------- */
function init(){
  buildDefsDyn();buildBg();buildRows();buildMowers();
  FX=new FxSys(L.fx,170);LFX=new FxSys(L.lawnFx,4);
  buildGhost();
  for(var i=0;i<26;i++){var el=makeSunEl();show(el.g,false);sunFree.push(el);}
  for(i=0;i<10;i++)popFree.push(makePop());
  buildHud();buildTitle();buildHelp();buildPause();buildOver();buildResults();buildBanner();
  CF=new FxSys(E('g',null,L.ovl),90);
  loadBest();goTitle();
  requestAnimationFrame(frame);
}
init();
})();
